    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int budget = (int) in.nval;
        int[] breads = new int[m], sauces = new int[n];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            breads[i] = (int) in.nval;
        }
        for (int i = 0; i < n; i++) {
            in.nextToken();
            sauces[i] = (int) in.nval;
        }
        Result r = closestBill(breads, sauces, budget);
        StringBuilder sb = new StringBuilder();
        sb.append(r.bill).append("\n").append(r.bread).append("\n").append(r.sauces.size());
        for (int j : r.sauces) sb.append(" ").append(j);
        System.out.println(sb);
